impl From<JsWebSocketMessage> for spikard_http::testing::WebSocketMessage {
    fn from(val: JsWebSocketMessage) -> Self {
        match val.type_tag.as_str() {
            "Text" => Self::Text(val.text.unwrap_or_default()),
            "Binary" => Self::Binary(val.binary.map(|b| b.to_vec()).unwrap_or_default()),
            "Close" => Self::Close {
                code: val.code.unwrap_or_default(),
                reason: val.reason,
            },
            "Ping" => Self::Ping(val.ping.map(|b| b.to_vec()).unwrap_or_default()),
            "Pong" => Self::Pong(val.pong.map(|b| b.to_vec()).unwrap_or_default()),
            _ => Self::Text(Default::default()),
        }
    }
}

impl From<spikard_http::testing::WebSocketMessage> for JsWebSocketMessage {
    fn from(val: spikard_http::testing::WebSocketMessage) -> Self {
        match val {
            spikard_http::testing::WebSocketMessage::Text(text) => Self {
                type_tag: "Text".to_string(),
                binary: None,
                code: None,
                ping: None,
                pong: None,
                reason: None,
                text: Some(text),
            },
            spikard_http::testing::WebSocketMessage::Binary(binary) => Self {
                type_tag: "Binary".to_string(),
                binary: Some(binary.into()),
                code: None,
                ping: None,
                pong: None,
                reason: None,
                text: None,
            },
            spikard_http::testing::WebSocketMessage::Close { code, reason } => Self {
                type_tag: "Close".to_string(),
                binary: None,
                code: Some(code),
                ping: None,
                pong: None,
                reason,
                text: None,
            },
            spikard_http::testing::WebSocketMessage::Ping(ping) => Self {
                type_tag: "Ping".to_string(),
                binary: None,
                code: None,
                ping: Some(ping.into()),
                pong: None,
                reason: None,
                text: None,
            },
            spikard_http::testing::WebSocketMessage::Pong(pong) => Self {
                type_tag: "Pong".to_string(),
                binary: None,
                code: None,
                ping: None,
                pong: Some(pong.into()),
                reason: None,
                text: None,
            },
        }
    }
}

