/// `gen_napi_error_class`), never smuggled into human-facing text.
#[allow(dead_code)]
fn app_error_to_napi_err(e: spikard::AppError) -> napi::Error {
    napi::Error::new(napi::Status::GenericFailure, e.to_string())
}

