/// The stable numeric error code is deliberately not interpolated into this message —
/// `napi::Error` has no per-variant subclass to attach it to. When available, it is exposed
/// as a structured `code` field on the `*Info` companion class instead (see
/// `gen_napi_error_class`), never smuggled into human-facing text.
#[allow(dead_code)]
fn graph_ql_error_to_napi_err(e: spikard_graphql::error::GraphQLError) -> napi::Error {
    napi::Error::new(napi::Status::GenericFailure, e.to_string())
}

#[napi]
pub struct JsGraphQLErrorInfo {
    pub code: u32,
    pub status_code: u16,
    pub is_transient: bool,
    pub error_type: String,
}

/// Resolve the stable numeric error code for a `spikard_graphql::error::GraphQLError` variant.
#[allow(dead_code)]
fn graph_ql_error_error_code(e: &spikard_graphql::error::GraphQLError) -> u32 {
    #[allow(unreachable_patterns)]
    match e {
        spikard_graphql::error::GraphQLError::ExecutionError(..) => 2,
        spikard_graphql::error::GraphQLError::SchemaBuildError(..) => 2,
        spikard_graphql::error::GraphQLError::RequestHandlingError(..) => 2,
        spikard_graphql::error::GraphQLError::SerializationError(..) => 2,
        spikard_graphql::error::GraphQLError::JsonError(..) => 2,
        spikard_graphql::error::GraphQLError::ValidationError(..) => 2,
        spikard_graphql::error::GraphQLError::ParseError(..) => 2,
        spikard_graphql::error::GraphQLError::AuthenticationError(..) => 2,
        spikard_graphql::error::GraphQLError::AuthorizationError(..) => 2,
        spikard_graphql::error::GraphQLError::NotFound(..) => 2,
        spikard_graphql::error::GraphQLError::RateLimitExceeded(..) => 2,
        spikard_graphql::error::GraphQLError::InvalidInput { .. } => 2,
        spikard_graphql::error::GraphQLError::ComplexityLimitExceeded => 2,
        spikard_graphql::error::GraphQLError::DepthLimitExceeded => 2,
        spikard_graphql::error::GraphQLError::IntrospectionDisabled => 2,
        spikard_graphql::error::GraphQLError::InternalError(..) => 2,
        _ => 2,
    }
}

#[allow(dead_code)]
fn graph_ql_error_info(e: &spikard_graphql::error::GraphQLError) -> JsGraphQLErrorInfo {
    JsGraphQLErrorInfo {
        code: graph_ql_error_error_code(e),
        status_code: e.status_code(),
        is_transient: e.is_transient(),
        error_type: e.error_type().to_string(),
    }
}

#[napi]
impl JsGraphQLErrorInfo {
    /// Stable numeric error code identifying the specific error variant.
    #[napi(js_name = "code")]
    pub fn code(&self) -> u32 {
        self.code
    }

    /// HTTP status code for this error (0 means no associated status).
    #[napi(js_name = "statusCode")]
    pub fn status_code(&self) -> u16 {
        self.status_code
    }

    /// Returns `true` if the error is transient and a retry may succeed.
    #[napi(js_name = "isTransient")]
    pub fn is_transient(&self) -> bool {
        self.is_transient
    }

    /// Machine-readable error category string for matching and logging.
    #[napi(js_name = "errorType")]
    pub fn error_type(&self) -> String {
        self.error_type.clone()
    }
}

